sysevent_script_action.script:
try {
    var createPosOndemand = new GlideRecord('x_hsb11_mss_pos_mss_custody_position_ondemand_staging');
    createPosOndemand.initialize();
    if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_trade") 
	{
        var sec_acc = current.securities_account;
        var countryTerritoryLocationCodes = sec_acc.substring(0, 2);
        var groupMemberIdentification = sec_acc.substring(3, 7);
        var safekeepingAccountIdentifications = sec_acc.substring(8, 22);
        createPosOndemand.request_body_for_detail = 'countryTerritoryLocationCode=' + countryTerritoryLocationCodes + '&groupMemberIdentification=' + groupMemberIdentification + '&safekeepingAccountIdentifications=' + safekeepingAccountIdentifications + '&hsbcIdentifiers=' + encodeURIComponent(current.security_id) + '&reportType=DETAIL';
        createPosOndemand.request_body_for_summary = 'countryTerritoryLocationCode=' + countryTerritoryLocationCodes + '&groupMemberIdentification=' + groupMemberIdentification + '&safekeepingAccountIdentifications=' + safekeepingAccountIdentifications + '&hsbcIdentifiers=' + encodeURIComponent(current.security_id) + '&reportType=SUMMARY';
        createPosOndemand.trade_reference = current.sys_id;
    } 
	else if (current.sys_class_name == "x_hsb11_mss_c_proc_mss_custody_task") 
	{
        var sec_acc = current.trade_id.securities_account;
        var countryTerritoryLocationCodes = sec_acc.substring(0, 2);
        var groupMemberIdentification = sec_acc.substring(3, 7);
        var safekeepingAccountIdentifications = sec_acc.substring(8, 22);
        createPosOndemand.request_body_for_detail = 'countryTerritoryLocationCode=' + countryTerritoryLocationCodes + '&groupMemberIdentification=' + groupMemberIdentification + '&safekeepingAccountIdentifications=' + safekeepingAccountIdentifications + '&hsbcIdentifiers=' + encodeURIComponent(current.trade_id.security_id) + '&reportType=DETAIL';
        createPosOndemand.request_body_for_summary = 'countryTerritoryLocationCode=' + countryTerritoryLocationCodes + '&groupMemberIdentification=' + groupMemberIdentification + '&safekeepingAccountIdentifications=' + safekeepingAccountIdentifications + '&hsbcIdentifiers=' + encodeURIComponent(current.trade_id.security_id) + '&reportType=SUMMARY';
        createPosOndemand.trade_reference = current.trade_id;
        createPosOndemand.task_reference = current.sys_id;
    }

    createPosOndemand.state_for_summary = 'ready_to_be_sent';
    createPosOndemand.request_date = new GlideDateTime();
	createPosOndemand.type = 'trade';
	createPosOndemand.insert();
} catch (e) {
    gs.info("The issue is " + e);
}
